import unittest

from step6_20260918191713_f99578f4 import normalize_label


class NormalizeLabelTests(unittest.TestCase):
    def test_strips_leading_and_trailing_whitespace(self) -> None:
        self.assertEqual(normalize_label("  hello  "), "hello")

    def test_strips_tabs_and_newlines(self) -> None:
        self.assertEqual(normalize_label("\t hello \n"), "hello")

    def test_no_whitespace_is_unchanged(self) -> None:
        self.assertEqual(normalize_label("hello"), "hello")

    def test_all_whitespace_becomes_empty_string(self) -> None:
        self.assertEqual(normalize_label("   "), "")


if __name__ == "__main__":
    unittest.main()

